import json
n=30
g=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for tr,r in enumerate(starts):
 for tc,c in enumerate(starts):
  for dr in range(5):
   for dc in range(5):
    rr,cc=r+dr,c+dc
    if rr<n and cc<n and (dr in (0,4) or dc in (0,4)):
     g[rr][cc]=4
for tr,r in enumerate(starts[:4]):
 for tc,c in enumerate(starts[:4]):
  for dr in range(1,4):
   for dc in range(1,4):
    g[r+dr][c+dc]=colors[tr][tc]
# horizontal signals, only the non-background colors (3 and 8)
for r in (2,3,4,16,17,18):
 for c in (6,7,13,14,20,21): g[r][c]=3
for r in (9,10,11,23,24,25):
 for c in (13,14): g[r][c]=8
# vertical signals
for c in list(range(2,5))+list(range(23,26)):
 for r in (6,7,13,14): g[r][c]=3
for c in list(range(9,12))+list(range(16,19)):
 for r in (13,14,20,21): g[r][c]=8
print(json.dumps(g,separators=(',',':')))
